mapper.select:
select f.fragment_id, f.document_id, f.goods_id, f.document_type, f.knowledge_version, f.content, f.rank_no from knowledge_fragment f inner join knowledge_document d on d.document_id = f.document_id where f.enabled = 1 and f.fragment_status = 'ENABLED' and d.enabled = 1 and d.document_status = 'ENABLED'
and (
f.content like concat('%', #{keyword}, '%') or f.document_type like concat('%', #{keyword}, '%')
)
order by (
case when f.content like concat('%', #{keyword}, '%') then 10 else 0 end + case when f.document_type like concat('%', #{keyword}, '%') then 5 else 0 end
) desc, f.rank_no asc
order by f.rank_no asc
limit #{limit}

select g.goods_id, g.goods_name, g.image_url, g.origin_price, a.group_price, g.spec_summary, g.after_sale_policy, g.recommend_reason, g.not_suitable_for, a.activity_id, a.team_size, timestampdiff(second, now(), a.end_time) as remaining_seconds from guide_goods g left join group_activity a on a.goods_id = g.goods_id and a.enabled = 1 and a.start_time <= now() and a.end_time > now() where g.enabled = 1
order by (
case when g.goods_name like concat('%', #{keyword}, '%') then 20 else 0 end + case when g.spec_summary like concat('%', #{keyword}, '%') then 16 else 0 end + case when g.recommend_reason like concat('%', #{keyword}, '%') then 12 else 0 end + case when g.not_suitable_for like concat('%', #{keyword}, '%') then -10 else 0 end
) desc, g.sort_order asc, g.id asc
order by g.sort_order asc, g.id asc
limit #{limit}
